beforeExample:
package test;

import org.eclipse.jface.internal.text.html.HTMLPrinter;

public class MyClass {
    public String processHtml(String content) {
        if (content != null) {
            return HTMLPrinter.convertToHTMLContent(content);
        }
        return null;
    }

    public void otherMethod() {
        String s = "test";
        String html = HTMLPrinter.convertToHTMLContent(s);
        System.out.println(html);
    }
}

afterExample:
package test;

import org.eclipse.jface.internal.text.html.HTMLPrinter;

public class MyClass {
    public String processHtml(String content) {
        if (content != null) {
            return HTMLPrinter.convertToHTMLContentWithWhitespace(content);
        }
        return null;
    }

    public void otherMethod() {
        String s = "test";
        String html = HTMLPrinter.convertToHTMLContentWithWhitespace(s);
        System.out.println(html);
    }
}

negativeExample:
package test;

import org.eclipse.jface.internal.text.html.HTMLPrinter;

public class MyClass {
    public String processNonHtml(String content) {
        return content.trim(); // Different method call, should not match
    }

    public String escapeContent(String content) {
        return HTMLPrinter.escapeForHTMLString(content); // Different method from HTMLPrinter, should not match
    }
}
